// TektonRun A Tekton TaskRun's status.
type TektonRun struct {
	CompletedAt *time.Time `json:"completed_at,omitempty"`
	Message     *string    `json:"message,omitempty"`
	Name        string     `json:"name"`
	Namespace   string     `json:"namespace"`

	// Phase Derived from the run's Succeeded condition.
	Phase TektonRunPhase `json:"phase"`

	// PodName The backing pod, once scheduled (stream logs from it).
	PodName   *string    `json:"pod_name,omitempty"`
	StartedAt *time.Time `json:"started_at,omitempty"`
}

// TektonRunPhase Derived from the run's Succeeded condition.
type TektonRunPhase string

// TektonRunRequest A minimal single-step job to run as a Tekton TaskRun.
type TektonRunRequest struct {
	// Image The container image the step runs in.
	Image string `json:"image"`

	// Name A name prefix for the run (a unique suffix is added).
	Name string `json:"name"`

	// Script The shell script the step executes.
	Script string `json:"script"`
}

// TektonStatus Whether a cluster is designated to run jobs (enabled) and the Tekton
// install lifecycle (status), reconciled with a live presence detection
// (present/controller_ready/detected_version). present and controller_ready
// reflect the most recent detection; enable/disable responses carry the
// stored state only, until the next status read or stream tick.
type TektonStatus struct {
	// ControllerReady Whether the Tekton controller has a ready replica.
	ControllerReady bool `json:"controller_ready"`

	// DetectedRevision The install-manifest revision stamped on the running controller by
	// the install that applied it, if detected. Absent for installs that
	// predate revision stamping — those read as update_available.
	DetectedRevision *string `json:"detected_revision,omitempty"`

	// DetectedVersion The running controller's reported version, if detected.
	DetectedVersion *string `json:"detected_version,omitempty"`

	// Enabled Whether this cluster is designated to run jobs.
	Enabled bool `json:"enabled"`

	// ExpectedRevision The revision of the install manifest set this Spacefleet would
	// apply. When a managed install's detected_revision differs, the
	// install is out of sync (even at the same Tekton version) and an
	// upgrade re-applies the manifest to converge it.
	ExpectedRevision string `json:"expected_revision"`

	// InstalledVersion The pinned Tekton version applied by the last install.
	InstalledVersion *string `json:"installed_version,omitempty"`

	// JobId Id of the in-flight install/uninstall job, for correlation.
	JobId         *string    `json:"job_id,omitempty"`
	LastCheckedAt *time.Time `json:"last_checked_at,omitempty"`

	// Managed Whether Tekton in this cluster was installed by Spacefleet. Upgrade
	// and delete are only offered when true — a Tekton installed outside
	// Spacefleet is never modified or removed.
	Managed bool `json:"managed"`

	// PinnedVersion The Tekton version Spacefleet installs (the upgrade target).
	PinnedVersion string `json:"pinned_version"`

	// Present Whether the Tekton API group is registered in the cluster.
	Present bool `json:"present"`

	// Status The Tekton install lifecycle for a cluster.
	//   - not_installed: Tekton is absent (or was uninstalled).
	//   - installing: a background job is installing Tekton.
	//   - installed: Tekton is present and the controller is ready.
	//   - upgrading: re-applying a newer pinned release.
	//   - failed: the last install/upgrade job errored (see status_message).
	//   - uninstalling: a background job is removing Tekton.
	Status TektonInstallStatus `json:"status"`

	// StatusMessage The last install-progress line, or the error when failed.
	StatusMessage *string `json:"status_message,omitempty"`

	// UpdateAvailable Whether the managed install differs from what this Spacefleet
	// expects — a newer pinned Tekton version, or a changed install
	// manifest set at the same version. Only ever true for a
	// Spacefleet-managed install. Like present/controller_ready it
	// reflects the most recent live detection; responses carrying stored
	// state only report false.
	UpdateAvailable bool `json:"update_available"`
}

// User defines model for User.
type User struct {
	Email string             `json:"email"`
	Id    openapi_types.UUID `json:"id"`
}

// Variable A named key/value passed to component jobs as an environment variable,
// defined at the group level (every application in the group), the app
// level (every component), or the component level. Lower levels are
// overridden by higher: group < app < component for a same-named variable.
// A sensitive variable's value is sealed at rest and never returned — only
// its name and the sensitive flag are.
type Variable struct {
	CreatedAt time.Time          `json:"created_at"`
	Id        openapi_types.UUID `json:"id"`

	// Name The environment variable name (a shell-safe identifier).
	Name string `json:"name"`

	// Sensitive When true, the value is sealed at rest and never returned (write-only,
	// it can only be replaced).
	Sensitive bool      `json:"sensitive"`
	UpdatedAt time.Time `json:"updated_at"`

	// Value The plaintext value. Present only for non-sensitive variables; a
	// sensitive variable's value is never returned.
	Value *string `json:"value,omitempty"`
}

// VariableCreateRequest defines model for VariableCreateRequest.
type VariableCreateRequest struct {
	// Name A shell-safe identifier, unique within the variable's scope.
	Name string `json:"name"`

	// Sensitive When true, the value is sealed at rest and never returned. Fixed at
	// creation (delete and recreate to change).
	Sensitive bool `json:"sensitive"`

	// Value The value. Required (a sensitive variable's must be non-empty); for a
	// non-sensitive variable an empty string is allowed.
	Value string `json:"value"`
}

// VariableUpdateRequest All fields optional. Omit `value` to leave it unchanged — the only way to
// keep a sensitive value, which is never returned. The sensitive flag is
// fixed at creation.
type VariableUpdateRequest struct {
	Name  *string `json:"name,omitempty"`
	Value *string `json:"value,omitempty"`
}

// Workflow An application's deploy workflow — its components plus any explicit group
// containers.
type Workflow struct {
	Components []Component      `json:"components"`
	Groups     []ComponentGroup `json:"groups"`
}

// WorkflowReplaceRequest The full set of components and group containers to replace the workflow
// with.
type WorkflowReplaceRequest struct {
	Components []ComponentInput       `json:"components"`
	Groups     *[]ComponentGroupInput `json:"groups,omitempty"`
}

// WorkflowRun One logical run of an application's deploy workflow.
type WorkflowRun struct {
	// Action What a workflow run does across the whole DAG.
	Action        RunAction          `json:"action"`
	ApplicationId openapi_types.UUID `json:"application_id"`
	CreatedAt     time.Time          `json:"created_at"`

	// FinishedAt When the run settled; absent until terminal.
	FinishedAt *time.Time         `json:"finished_at,omitempty"`
	Id         openapi_types.UUID `json:"id"`

	// Message Human-readable detail (a progress line, or the summary).
	Message *string `json:"message,omitempty"`

	// StartedAt When the run started executing; absent while pending.
	StartedAt *time.Time `json:"started_at,omitempty"`

	// Status The run's lifecycle: pending → running → a terminal succeeded / failed /
	// partial (partial = only continue-on-failure nodes failed). A run parked
	// at a manual-approval gate is awaiting_approval (a non-terminal pause)
	// until an approve/reject decision resumes it.
	Status RunStatus `json:"status"`
}

// WorkflowRunDetail defines model for WorkflowRunDetail.
type WorkflowRunDetail struct {
	// Action What a workflow run does across the whole DAG.
	Action        RunAction          `json:"action"`
	ApplicationId openapi_types.UUID `json:"application_id"`
	ComponentRuns []ComponentRun     `json:"component_runs"`
	CreatedAt     time.Time          `json:"created_at"`

	// FinishedAt When the run settled; absent until terminal.
	FinishedAt *time.Time `json:"finished_at,omitempty"`

	// Graph JSON snapshot of the workflow graph (nodes + edges + config) as it
	// was when the run began. Secret-bearing config is redacted for
	// callers below editor.
	Graph *string            `json:"graph,omitempty"`
	Id    openapi_types.UUID `json:"id"`

	// Message Human-readable detail (a progress line, or the summary).
	Message *string `json:"message,omitempty"`

	// StartedAt When the run started executing; absent while pending.
	StartedAt *time.Time `json:"started_at,omitempty"`

	// Status The run's lifecycle: pending → running → a terminal succeeded / failed /
	// partial (partial = only continue-on-failure nodes failed). A run parked
	// at a manual-approval gate is awaiting_approval (a non-terminal pause)
	// until an approve/reject decision resumes it.
	Status RunStatus `json:"status"`
}

